        "description": "空调动作区文字符号",
        "sampleValue": "[风]"
      },
      "curtainGlyph": {
        "type": "string",
        "description": "窗帘动作区文字符号",
        "sampleValue": "[窗]"
      }
    }
  },
  "assetCandidates": []
}

